<template><div class="app-container"><el-page-header content="待办运营中心"/><operations-metrics :rows="metrics"/><el-tabs v-model="tab"><el-tab-pane label="超时与升级" name="escalations"><div class="toolbar"><el-button v-hasPermi="['todo:batch:transfer']" :disabled="!selected.length" @click="batchTransfer">批量转派</el-button></div><escalation-table :rows="overdue" @selection="selected=$event" @action="openAction"/></el-tab-pane><el-tab-pane label="失败事件" name="events"><event-failure-table :rows="events" :loading="loadingEvents" @replay="replay"/></el-tab-pane></el-tabs><exception-action-dialog :visible.sync="dialog" :todo="current" :submitting="submitting" @submit="execute"/></div></template>
<script>import OperationsMetrics from './components/OperationsMetrics';import EventFailureTable from './components/EventFailureTable';import EscalationTable from './components/EscalationTable';import ExceptionActionDialog from './components/ExceptionActionDialog';import {listTodo} from '@/api/todo';import {getOperationsDashboard,listDeadEvents,replayDeadEvent,forceCompleteTodo,forceCancelTodo,regenerateTodo,batchTransferTodos,waiveTodoSla} from '@/api/todo-operations';export default{name:'TodoOperations',components:{OperationsMetrics,EventFailureTable,EscalationTable,ExceptionActionDialog},data(){return{tab:'escalations',metrics:[],overdue:[],events:[],selected:[],current:null,dialog:false,submitting:false,loadingEvents:false}},created(){this.load()},methods:{load(){getOperationsDashboard().then(r=>{this.metrics=r.data||[]});listTodo({mode:'overdue',pageNum:1,pageSize:200}).then(r=>{this.overdue=r.rows||[]});this.loadingEvents=true;listDeadEvents({pageNum:1,pageSize:100}).then(r=>{this.events=r.rows||[]}).finally(()=>{this.loadingEvents=false})},replay(row){this.$confirm('仅重新投递 DEAD 事件，消费端仍会执行幂等检查。确认重放？','事件重放',{type:'warning'}).then(()=>replayDeadEvent(row.eventId)).then(()=>{this.$modal.msgSuccess('已重新入队');this.load()})},openAction(row){this.current=row;this.dialog=true},execute(form){const id=this.current.todo_id,data={actionId:`ops-${Date.now()}`,reason:form.reason,payload:{}};const calls={'force-complete':forceCompleteTodo,'force-cancel':forceCancelTodo,regenerate:regenerateTodo};this.submitting=true;const call=form.action==='sla-waiver'?waiveTodoSla(id,{actionId:data.actionId,reason:form.reason,newDueAt:form.newDueAt}):calls[form.action](id,data);call.then(()=>{this.$modal.msgSuccess('操作成功');this.dialog=false;this.load()}).finally(()=>{this.submitting=false})},batchTransfer(){this.$prompt('请输入目标负责人ID','批量转派',{inputPattern:/^\d+$/}).then(({value})=>this.$prompt('请输入转派原因','批量转派原因',{inputValidator:v=>!!v} ).then(({value:reason})=>batchTransferTodos({actionId:`batch-${Date.now()}`,todoIds:this.selected.map(x=>x.todo_id),targetOwnerId:Number(value),reason}))).then(()=>{this.$modal.msgSuccess('批量转派成功');this.load()})}}}</script><style scoped>.toolbar{margin:0 0 12px}</style>
